<?php
session_start(); require_once('check-login.php'); require_once('smartmark-utils.php'); smartmark_ensure_tables($con);
if(!(isset($_SESSION['ACCESSLEVEL'],$_SESSION['SYSTEMTYPE'])&&$_SESSION['ACCESSLEVEL']==='user'&&$_SESSION['SYSTEMTYPE']==='Teacher')){http_response_code(403);exit('Access denied.');}
$teacherEsc=mysqli_real_escape_string($con,(string)$_SESSION['USERID']);$id=(int)($_GET['assessment']??0);$res=@mysqli_query($con,"SELECT title FROM tblsmartmarkassessment WHERE assessmentid=$id AND teacherid='$teacherEsc' LIMIT 1");$assessment=$res?mysqli_fetch_array($res,MYSQLI_ASSOC):null;if(!$assessment){http_response_code(404);exit('Assessment not found.');}
header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="smartmark-results-'.$id.'.csv"');$out=fopen('php://output','w');fputcsv($out,array('Student ID','Student','Score','Total','Percentage','Correct','Incorrect','Blank','Multiple','Review required','Status','Last updated'));
$sql="SELECT t.*,CONCAT_WS(' ',NULLIF(TRIM(u.firstname),''),NULLIF(TRIM(u.othernames),''),NULLIF(TRIM(u.surname),'')) student_name FROM tblsmartmarkattempt t LEFT JOIN tblsystemuser u ON u.userid=t.studentid WHERE t.assessmentid=$id ORDER BY student_name,t.studentid";$rows=@mysqli_query($con,$sql);if($rows){while($row=mysqli_fetch_array($rows,MYSQLI_ASSOC)){fputcsv($out,array($row['studentid'],trim($row['student_name']),$row['score'],$row['totalscore'],$row['percentage'].'%',$row['correctcount'],$row['incorrectcount'],$row['blankcount'],$row['multiplecount'],$row['reviewcount'],$row['status'],$row['updatedat']));}}fclose($out);
?>
